-- changelog(seq, op, id, name, price) : op = c 생성 / u 수정 / d 삭제
SELECT id, name, price FROM (
  SELECT *, ROW_NUMBER() OVER (PARTITION BY id ORDER BY seq DESC) AS rn
  FROM changelog
) WHERE rn = 1 AND op <> 'd';

