resource "google_bigquery_dataset" "travel_mart" {
  dataset_id = "travel_mart"
  location   = "asia-northeast1"

  access {
    role           = "READER"
    group_by_email = "travel-analysts@example.com"
  }
}

REQUIRED = {"event_id", "event_name", "user_id", "ts", "page"}
events = [
  {"event_id": "e1", "event_name": "view_item", "user_id": "u1", "ts": "2026-11-20T10:00:00+09:00", "page": "/hotel/10"},
  {"event_id": "e2", "event_name": "click_reserve", "user_id": "u1", "ts": "2026-11-20T10:00:05+09:00"},
  {"event_id": "e1", "event_name": "view_item", "user_id": "u1", "ts": "2026-11-20T10:00:00+09:00", "page": "/hotel/10"},
]
seen, ok, bad = set(), [], []
for e in events:
    miss = REQUIRED - e.keys()
    if miss:
        bad.append((e["event_id"], "빠진 칸 " + ",".join(sorted(miss))))
    elif e["event_id"] in seen:
        bad.append((e["event_id"], "중복"))
    else:
        seen.add(e["event_id"]); ok.append(e["event_id"])
print("ok", ok)    # ok ['e1']
print("bad", bad)  # bad [('e2', '빠진 칸 page'), ('e1', '중복')]

